const cfg = $input.first().json;
const state = $getWorkflowStaticData('global');

const cities = Array.isArray(cfg.cities) ? cfg.cities.filter(c => c?.city) : [];
const keywords = Array.isArray(cfg.keywords)
  ? cfg.keywords.map(k => String(k || '').trim()).filter(Boolean)
  : [];

if (!cities.length) throw new Error('No cities configured');
if (!keywords.length) throw new Error('No keywords configured');

const candidates = [];
for (const cityConfig of cities) {
  for (const category of keywords) {
    candidates.push({
      ...cityConfig,
      category,
      keyword: `${category} in ${cityConfig.city}, Pakistan`,
    });
  }
}

let cursor = Number(state.searchRotationCursor ?? 0);
if (!Number.isInteger(cursor) || cursor < 0 || cursor >= candidates.length) cursor = 0;

const requested = Math.max(1, Math.floor(Number(cfg?.limits?.keywordsPerRun || 1)));
const count = Math.min(requested, candidates.length);
const nextCursor = (cursor + count) % candidates.length;
const run = Number(state.searchRotationRuns ?? 0) + 1;

const out = [];
for (let i = 0; i < count; i++) {
  const index = (cursor + i) % candidates.length;
  out.push({
    json:{
      ...cfg,
      ...candidates[index],
      industry:cfg.niche,
      rotation:{
        index,
        position:index + 1,
        total:candidates.length,
        cursor_before:cursor,
        cursor_after:nextCursor,
        batch_position:i + 1,
        batch_size:count,
        run
      }
    }
  });
}

state.searchRotationCursor = nextCursor;
state.searchRotationRuns = run;
return out;

const out = [];

function clean(value) {
  const s = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (!s || /^(?:n\/?a|na|none|null|unknown|-|—)$/i.test(s)) return '';
  return s;
}

function phone(value) {
  const s = clean(value);
  if (!s) return '';
  const p = s.replace(/[^0-9+]/g, '');
  return p.length >= 7 ? p : '';
}

function website(value) {
  let s = clean(value);
  if (!s) return '';
  if (!/^https?:\/\//i.test(s)) s = `https://${s}`;
  try {
    const u = new URL(s);
    if (!/^https?:$/.test(u.protocol)) return '';
    return u.href;
  } catch {
    return '';
  }
}

function mapsUrl(value) {
  const s = clean(value);
  if (!s) return '';
  try {
    const u = new URL(s);
    u.search = '';
    u.hash = '';
    return u.toString();
  } catch {
    return s;
  }
}

for (const item of $input.all()) {
  const j = item.json;
  const query = clean(j.keyword);

  if (!query) {
    out.push({json:{...j,_skipUpsert:true,skipReason:'empty_search_keyword'}});
    continue;
  }

  let response;
  try {
    response = await this.helpers.httpRequest({
      method:'POST',
      url:`${String(j.scraper?.baseUrl || '').replace(/\/$/, '')}/api/scrape/search`,
      headers:{'Content-Type':'application/json'},
      body:{
        query,
        maxResults:Math.max(1, Math.min(12, Number(j.limits?.maxResultsPerKeyword || 12)))
      },
      json:true,
      timeout:240000
    });
  } catch (e) {
    out.push({json:{
      ...j,
      _skipUpsert:true,
      skipReason:'google_maps_scrape_failed',
      scrapeError:String(e.message || e)
    }});
    continue;
  }

  const results = Array.isArray(response?.data?.results) ? response.data.results : [];

  if (!results.length) {
    out.push({json:{
      ...j,
      _skipUpsert:true,
      skipReason:'google_maps_no_results'
    }});
    continue;
  }

  for (const p of results) {
    const businessName = clean(p?.title);
    const googleMapsUrl = mapsUrl(p?.googleMapsUrl || p?.url);
    const businessWebsite = website(p?.website);
    const businessPhone = phone(p?.phone);

    if (!businessName || (!googleMapsUrl && !businessWebsite && !businessPhone)) continue;

    let domain = '';
    if (businessWebsite) {
      try { domain = new URL(businessWebsite).hostname.replace(/^www\./i, '').toLowerCase(); } catch {}
    }

    const mapEmail = clean(p?.email).toLowerCase();

    out.push({json:{
      ...j,
      businessName,
      address:clean(p?.address),
      phone:businessPhone,
      website:businessWebsite,
      domain,
      googleMapsUrl,
      latitude:Number.isFinite(Number(p?.latitude)) ? Number(p.latitude) : null,
      longitude:Number.isFinite(Number(p?.longitude)) ? Number(p.longitude) : null,
      rating:Number.isFinite(Number(p?.rating)) ? Number(p.rating) : null,
      reviews:Math.max(0, Number(String(p?.reviews || '').replace(/[^0-9]/g, '')) || 0),
      rawCategory:clean(p?.category || j.category),
      sourceRetrievedAt:new Date().toISOString(),
      mapEmails:mapEmail ? [mapEmail] : []
    }});
  }

  if (!out.some(x => x.json.keyword === j.keyword && !x.json._skipUpsert)) {
    out.push({json:{...j,_skipUpsert:true,skipReason:'google_maps_results_unusable'}});
  }
}

return out;

const inputs = $input.all();

function uniq(a) { return [...new Set(a.filter(Boolean))]; }
function clean(v) {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (!s || /^(?:n\/?a|na|none|null|unknown|-|—)$/i.test(s)) return '';
  return s;
}
function htmlToText(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&(?:nbsp|amp|quot|apos|lt|gt);/gi, ' ')
    .replace(/&#\d+;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function normalizeEmail(v) {
  return String(v || '').trim().toLowerCase().replace(/^mailto:/i, '').replace(/^[<(\"'\s]+/, '').replace(/[>)\"'\],.;:\s]+$/, '');
}
function validEmailSyntax(email) {
  if (!email || email.length > 254) return false;
  const at = email.lastIndexOf('@');
  if (at <= 0) return false;
  const local = email.slice(0, at), domain = email.slice(at + 1);
  if (!local || !domain || local.length > 64 || domain.length > 253) return false;
  if (local.startsWith('.') || local.endsWith('.') || local.includes('..')) return false;
  if (!/^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+$/i.test(local)) return false;
  const labels = domain.split('.');
  if (labels.length < 2) return false;
  for (const label of labels) {
    if (!label || label.length > 63 || !/^[a-z0-9-]+$/i.test(label) || label.startsWith('-') || label.endsWith('-')) return false;
  }
  return /^[a-z]{2,63}$/i.test(labels.at(-1));
}
function assetGarbage(email) {
  const lower = email.toLowerCase();
  const [local='', domain=''] = lower.split('@');
  return /\.(?:png|jpe?g|gif|webp|svg|ico|css|js|woff2?|ttf|eot|pdf|zip)$/i.test(domain) ||
    /^(?:logo|icon|sprite|favicon|image|img|avatar|banner|thumbnail|thumb)(?:[-_.]|$)/i.test(local) ||
    /@(?:2x|3x)\.(?:png|jpe?g|gif|webp)$/i.test(lower);
}
function sanitizeEmails(values) {
  return uniq(values.map(normalizeEmail).filter(e => validEmailSyntax(e) && !assetGarbage(e)));
}
function pageUrls(site, limit) {
  if (!site) return [];
  try {
    const origin = new URL(site).origin;
    const paths = ['', '/about', '/contact', '/about-us', '/team', '/leadership'];
    return uniq(paths.slice(0, Math.max(1, Math.min(6, limit))).map(p => new URL(p, origin).href));
  } catch { return []; }
}
async function mapLimit(items, limit, worker) {
  const results = new Array(items.length);
  let cursor = 0;
  async function run() {
    while (true) {
      const i = cursor++;
      if (i >= items.length) return;
      results[i] = await worker(items[i], i);
    }
  }
  await Promise.all(Array.from({length:Math.min(limit, items.length)}, run));
  return results;
}

const concurrency = Math.max(1, Math.min(5, Number(inputs[0]?.json?.limits?.websiteConcurrency || 3)));
const results = await mapLimit(inputs, concurrency, async item => {
  const j = item.json;
  if (j._skipUpsert) return {json:{...j,emails:[],socialProfiles:{linkedin:[],facebook:[],instagram:[]},websiteText:'',websiteSignals:{hasWebsite:false,emailCandidateCount:0,emailCount:0,linkedinCount:0,pagesCrawled:[]},contacts:[]}};

  const urls = pageUrls(j.website, Number(j.limits?.crawlPagesPerSite || 3));
  const pages = await Promise.all(urls.map(async url => {
    try {
      const html = await this.helpers.httpRequest({
        method:'GET',
        url,
        timeout:8000,
        followRedirect:true,
        maxRedirects:5,
        headers:{
          'User-Agent':'Mozilla/5.0 (compatible; SRLINES-LeadResearch/1.0)',
          'Accept':'text/html,application/xhtml+xml'
        },
        json:false
      });
      return {url,html:String(html || '')};
    } catch { return null; }
  }));

  const goodPages = pages.filter(Boolean);
  const combined = goodPages.map(p => p.html).join('\n');
  const candidates = [
    ...(Array.isArray(j.mapEmails) ? j.mapEmails : []),
    ...(combined.match(/[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9.-]+\.[A-Z]{2,63}/gi) || [])
  ];
  const emails = sanitizeEmails(candidates);
  const linkedin = uniq(combined.match(/https?:\/\/(?:[a-z]+\.)?linkedin\.com\/(?:in|company)\/[A-Za-z0-9_%?&=./-]+/gi) || []);
  const facebook = uniq(combined.match(/https?:\/\/(?:www\.)?facebook\.com\/[A-Za-z0-9_.?&=/-]+/gi) || []);
  const instagram = uniq(combined.match(/https?:\/\/(?:www\.)?instagram\.com\/[A-Za-z0-9_.?&=/-]+/gi) || []);

  return {json:{
    ...j,
    emails,
    socialProfiles:{linkedin,facebook,instagram},
    websiteText:htmlToText(combined).slice(0,18000),
    websiteSignals:{
      hasWebsite:!!j.website,
      emailCandidateCount:candidates.length,
      emailCount:emails.length,
      linkedinCount:linkedin.length,
      pagesAttempted:urls,
      pagesCrawled:goodPages.map(p => p.url)
    },
    contacts:[]
  }};
});

return results;

const inputs = $input.all();
const cfg = $('Pakistan Runtime Config').first().json;
let apiDisabledReason = '';

function fallback(j) {
  let s = 20;
  if (j.website) s += 15;
  if (Array.isArray(j.emails) && j.emails.length) s += 15;
  if (j.socialProfiles?.linkedin?.length) s += 10;
  if ((j.reviews || 0) >= 50) s += 10;
  if ((j.reviews || 0) >= 200) s += 10;
  if ((j.rating || 0) >= 4) s += 10;
  return Math.min(100, s);
}
function gradeFor(score) {
  return score >= 80 ? 'A' : score >= 65 ? 'B' : score >= 45 ? 'C' : 'D';
}
async function mapLimit(items, limit, worker) {
  const results = new Array(items.length);
  let cursor = 0;
  async function run() {
    while (true) {
      const i = cursor++;
      if (i >= items.length) return;
      results[i] = await worker(items[i], i);
    }
  }
  await Promise.all(Array.from({length:Math.min(limit, items.length)}, run));
  return results;
}

const concurrency = Math.max(1, Math.min(4, Number(cfg?.limits?.aiConcurrency || 3)));
const results = await mapLimit(inputs, concurrency, async item => {
  const j = item.json;
  if (j._skipUpsert) return {json:{...j,score:0,grade:'D',qualification:'Skipped: no usable Google Maps lead.',nurtureStrategy:'',contacts:[],aiAnalysis:{skipped:true,reason:j.skipReason || 'invalid_lead'}}};

  const base = fallback(j);
  const fallbackAi = {
    score:base,
    grade:gradeFor(base),
    qualification:'Heuristic score; AI was unavailable or there was insufficient public evidence.',
    nurture_strategy:'Research and verify a senior decision-maker before outreach.',
    contacts:[]
  };

  const hasEvidence = !!String(j.websiteText || '').trim() || (j.emails?.length || 0) > 0 || (j.socialProfiles?.linkedin?.length || 0) > 0;
  if (!hasEvidence) {
    return {json:{...j,score:base,grade:gradeFor(base),qualification:fallbackAi.qualification,nurtureStrategy:fallbackAi.nurture_strategy,contacts:[],aiAnalysis:{...fallbackAi,skipped:true,reason:'insufficient_public_website_evidence'}}};
  }

  if (apiDisabledReason) {
    return {json:{...j,score:base,grade:gradeFor(base),qualification:fallbackAi.qualification,nurtureStrategy:fallbackAi.nurture_strategy,contacts:[],aiAnalysis:{...fallbackAi,error:apiDisabledReason}}};
  }

  let ai = {...fallbackAi};
  try {
    if (!cfg.deepseek?.apiKey || cfg.deepseek.apiKey.startsWith('PASTE_')) throw new Error('DeepSeek key is not configured');

    const prompt = `Research/qualification task only; do not write or send outreach. Use ONLY the supplied public evidence. Return one JSON object with: score (0-100), grade (A/B/C/D), qualification, nurture_strategy, contacts. Each contacts item may contain full_name, job_title, authority_level (owner/c-suite/director/manager/unknown), email, phone, linkedin_url, source_url, confidence (0-100), is_decision_maker. Never invent a person or contact detail. If a person is not explicitly supported by the evidence, do not include them. Lead evidence: ${JSON.stringify({business:j.businessName,city:j.city,category:j.rawCategory,rating:j.rating,reviews:j.reviews,emails:j.emails,socialProfiles:j.socialProfiles,website:j.website,websiteText:String(j.websiteText || '').slice(0,12000)})}`;

    const r = await this.helpers.httpRequest({
      method:'POST',
      url:cfg.deepseek.apiUrl,
      headers:{Authorization:`Bearer ${cfg.deepseek.apiKey}`,'Content-Type':'application/json'},
      body:{
        model:cfg.deepseek.model,
        temperature:0.1,
        messages:[{role:'user',content:prompt}],
        response_format:{type:'json_object'}
      },
      json:true,
      timeout:45000
    });

    const parsed = JSON.parse(r?.choices?.[0]?.message?.content || '{}');
    ai = {...ai,...parsed};
  } catch (e) {
    const message = String(e.message || e);
    ai.error = message;
    if (/status code 402|\b402\b|payment|required|balance/i.test(message)) apiDisabledReason = message;
  }

  const score = Math.max(0, Math.min(100, Math.round(Number(ai.score) || base)));
  const contacts = Array.isArray(ai.contacts) ? ai.contacts.filter(c => c && typeof c === 'object') : [];

  return {json:{
    ...j,
    score,
    grade:/^[ABCD]$/i.test(String(ai.grade || '')) ? String(ai.grade).toUpperCase() : gradeFor(score),
    qualification:String(ai.qualification || fallbackAi.qualification),
    nurtureStrategy:String(ai.nurture_strategy || fallbackAi.nurture_strategy),
    contacts,
    aiAnalysis:ai
  }};
});

return results;

