  const [local='', domain=''] = lower.split('@');
  return /\.(?:png|jpe?g|gif|webp|svg|ico|css|js|woff2?|ttf|eot|pdf|zip)$/i.test(domain) ||
    /^(?:logo|icon|sprite|favicon|image|img|avatar|banner|thumbnail|thumb)(?:[-_.]|$)/i.test(local) ||
    /@(?:2x|3x)\.(?:png|jpe?g|gif|webp)$/i.test(lower);
}
async function mxFor(domain) {
  if (mxCache.has(domain)) return mxCache.get(domain);
  let result;
  try {
    const r = await this.helpers.httpRequest({
      method:'GET',
      url:'https://dns.google/resolve',
      qs:{name:domain,type:'MX'},
      headers:{Accept:'application/dns-json'},
      json:true,
      timeout:8000
    });
    const answers = Array.isArray(r?.Answer) ? r.Answer : [];
    const records = answers.filter(x => Number(x.type) === 15).map(x => String(x.data || '').trim()).filter(Boolean);
    const nullMx = records.some(x => /^0\s+\.$/.test(x));
    result = {valid:records.length > 0 && !nullMx,records,reason:nullMx?'null_mx':records.length?'mx_found':'no_mx'};
  } catch (e) {
    result = {valid:false,records:[],reason:`dns_error:${String(e.message || e)}`};
  }
  mxCache.set(domain, result);
  return result;
}
async function validateEmail(raw) {
  const email = normalizeEmail(raw);
  if (!validSyntax(email)) return {email,valid:false,syntax_valid:false,mx_valid:false,mx_records:[],reason:'invalid_syntax'};
  if (assetGarbage(email)) return {email,valid:false,syntax_valid:true,mx_valid:false,mx_records:[],reason:'asset_or_scraper_junk'};
  const mx = await mxFor(email.split('@')[1]);
  return {email,valid:mx.valid,syntax_valid:true,mx_valid:mx.valid,mx_records:mx.records,reason:mx.reason};
}
async function mapLimit(items, limit, worker) {
  const results = new Array(items.length);
  let cursor = 0;
  async function run() {
    while (true) {
      const i = cursor++;
      if (i >= items.length) return;
      results[i] = await worker(items[i], i);
    }
  }
  await Promise.all(Array.from({length:Math.min(limit, items.length)}, run));
  return results;
}

const concurrency = Math.max(1, Math.min(10, Number(inputs[0]?.json?.limits?.mxConcurrency || 6)));
const results = await mapLimit(inputs, concurrency, async item => {
  const data = {...item.json};

  data.businessName = clean(data.businessName);
  data.city = clean(data.city);
  data.province = clean(data.province);
  data.address = clean(data.address);
  data.phone = cleanPhone(data.phone);
  data.website = clean(data.website);
  data.domain = clean(data.domain).toLowerCase();
  data.googleMapsUrl = clean(data.googleMapsUrl);

  if (data._skipUpsert) {
    data.emails = [];
    data.contacts = [];
    data.decision_makers = [];
    data.emailValidation = [];
    data.emailValidationSummary = {candidates:0,valid:0,rejected:0,rejectedEmails:[]};
    return {json:data};
  }

  const rawEmails = [...new Set((Array.isArray(data.emails) ? data.emails : []).map(normalizeEmail).filter(Boolean))];
  const emailValidation = await Promise.all(rawEmails.map(validateEmail));
  data.emails = emailValidation.filter(x => x.valid).map(x => x.email);

  const sourceContacts = Array.isArray(data.contacts) ? data.contacts : [];
  const cleanedContacts = [];

  for (const raw of sourceContacts) {
    if (!raw || typeof raw !== 'object') continue;
    const c = {...raw};
    c.full_name = clean(c.full_name) || null;
    c.job_title = clean(c.job_title) || null;
    c.authority_level = clean(c.authority_level).toLowerCase() || 'unknown';
    c.phone = cleanPhone(c.phone) || null;
    c.linkedin_url = clean(c.linkedin_url) || null;
    c.source_url = clean(c.source_url) || null;
    c.confidence = Math.max(0, Math.min(100, Number.parseInt(c.confidence, 10) || 0));
    c.is_decision_maker = c.is_decision_maker === true || c.is_decision_maker === 1 || /^(?:1|true|yes|y)$/i.test(String(c.is_decision_maker || ''));

    if (c.email) {
      const ev = await validateEmail(c.email);
      c.email_validation = ev;
      c.email = ev.valid ? ev.email : null;
    } else {
      c.email = null;
    }

    if (c.full_name || c.email || c.linkedin_url || c.phone) cleanedContacts.push(c);
  }

  const seen = new Set();
  data.contacts = cleanedContacts.filter(c => {
    const key = String(c.email || c.linkedin_url || c.phone || `${c.full_name || ''}|${c.job_title || ''}`).toLowerCase().trim();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  data.decision_makers = data.contacts;
  data.emailValidation = emailValidation;
  data.emailValidationSummary = {
    candidates:emailValidation.length,
    valid:emailValidation.filter(x => x.valid).length,
    rejected:emailValidation.filter(x => !x.valid).length,
    rejectedEmails:emailValidation.filter(x => !x.valid).map(x => ({email:x.email,reason:x.reason}))
  };

  const hasLocator = !!(data.googleMapsUrl || data.domain || data.phone || data.website);
  if (!data.businessName || !data.city || !hasLocator) {
    data._skipUpsert = true;
    data.skipReason = !data.businessName ? 'missing_business_name' : !data.city ? 'missing_city' : 'missing_business_locator';
  }

  return {json:data};
});

return results;

